/*
 * NT36532 application images for liuqin_nvt.c.
 *
 * This default carries none. When LIUQIN_TOUCH_FW_DIR names a directory with
 * novatek_nt36532_m81_fw_csot.bin and/or novatek_nt36532_m81_fw_tm.bin, the
 * kernel build replaces this file in the XNU work tree with one generated by
 * scripts/gen-liuqin-touch-fw.py. The images are vendor files: they reach only
 * the built kernel, which leaves CI encrypted, never the repository.
 */
#ifndef LIUQIN_NVT_FW_H
#define LIUQIN_NVT_FW_H
#include <stdint.h>

static const uint8_t liuqin_nvt_fw_csot[1] = { 0 };
static const uint32_t liuqin_nvt_fw_csot_size = 0;
static const uint8_t liuqin_nvt_fw_tm[1] = { 0 };
static const uint32_t liuqin_nvt_fw_tm_size = 0;
#endif
